"Вы загружаете фото комнаты, стены или фасада и указываете площадь. Сервис определяет вид работ, считает объёмы и материалы и оценивает стоимость по ценовой базе ЭСН РК (23 864 позиции) с поправкой на регион. Вы получаете три варианта цены: эконом, стандарт и премиум.":"Sie laden ein Foto des Raums, der Wand oder der Fassade hoch und geben die Fläche an. Der Service erkennt die Art der Arbeiten, berechnet Mengen und Materialien und schätzt die Kosten anhand der Preisdatenbank ESN RK (23 864 Positionen) mit regionaler Anpassung. Sie erhalten drei Preisvarianten: Economy, Standard und Premium.",
"Вы загружаете фото комнаты, стены или фасада и указываете площадь. Сервис определяет вид работ, считает объёмы и материалы и оценивает стоимость по ценовой базе ЭСН РК (23 864 позиции) с поправкой на регион. Вы получаете три варианта цены: эконом, стандарт и премиум":"Sie laden ein Foto des Raums, der Wand oder der Fassade hoch und geben die Fläche an. Der Service erkennt die Art der Arbeiten, berechnet Mengen und Materialien und schätzt die Kosten anhand der Preisdatenbank ESN RK (23 864 Positionen) mit regionaler Anpassung. Sie erhalten drei Preisvarianten: Economy, Standard und Premium",
"Вы загружаете фото комнаты, стены или фасада и указываете площадь. Сервис определяет вид работ, считает объёмы и материалы и оценивает стоимость по ценовой базе ЭСН РК ({n} позиции) с поправкой на регион. Вы получаете три варианта цены: эконом, стандарт и премиум":"Sie laden ein Foto des Raums, der Wand oder der Fassade hoch und geben die Fläche an. Der Service erkennt die Art der Arbeiten, berechnet Mengen und Materialien und schätzt die Kosten anhand der Preisdatenbank ESN RK ({n} Positionen) mit regionaler Anpassung. Sie erhalten drei Preisvarianten: Economy, Standard und Premium",
"Насколько точна проверка дефектов?":"Wie genau ist die Mängelprüfung?",
"Насколько точна проверка дефектов":"Wie genau ist die Mängelprüfung",
"Нейросеть обучена на размеченных фото трещин: она отмечает трещины рамкой и показывает уверенность для каждой зоны. Коррозию, сколы, высолы и влагу модель пока не подтверждает — их оценивает инженер на осмотре. Заключение помечено как предварительное, пока его не подтвердит специалист.":"Das neuronale Netz wurde mit annotierten Rissfotos trainiert: Es rahmt Risse ein und zeigt für jeden Bereich die Sicherheit an. Korrosion, Abplatzungen, Ausblühungen und Feuchtigkeit bestätigt das Modell noch nicht — sie beurteilt der Ingenieur bei der Besichtigung. Das Ergebnis gilt als vorläufig, bis ein Fachmann es bestätigt.",
"Нейросеть обучена на размеченных фото трещин: она отмечает трещины рамкой и показывает уверенность для каждой зоны. Коррозию, сколы, высолы и влагу модель пока не подтверждает — их оценивает инженер на осмотре. Заключение помечено как предварительное, пока его не подтвердит специалист":"Das neuronale Netz wurde mit annotierten Rissfotos trainiert: Es rahmt Risse ein und zeigt für jeden Bereich die Sicherheit an. Korrosion, Abplatzungen, Ausblühungen und Feuchtigkeit bestätigt das Modell noch nicht — sie beurteilt der Ingenieur bei der Besichtigung. Das Ergebnis gilt als vorläufig, bis ein Fachmann es bestätigt",
"Как найти исполнителя?":"Wie finde ich einen Auftragnehmer?",
"Как найти исполнителя":"Wie finde ich einen Auftragnehmer",
"Откройте каталог подрядчиков и позвоните бригаде напрямую или опубликуйте заказ в ленте — исполнители из вашего города пришлют предложения по цене и срокам. Заявка отправляется без предоплаты: цену и оплату вы согласуете с исполнителем напрямую.":"Öffnen Sie den Katalog der Bauunternehmen und rufen Sie ein Team direkt an oder veröffentlichen Sie einen Auftrag im Feed — Auftragnehmer aus Ihrer Stadt senden Angebote mit Preis und Terminen. Die Anfrage wird ohne Vorauszahlung gesendet: Preis und Bezahlung vereinbaren Sie direkt mit dem Auftragnehmer.",
"Откройте каталог подрядчиков и позвоните бригаде напрямую или опубликуйте заказ в ленте — исполнители из вашего города пришлют предложения по цене и срокам. Заявка отправляется без предоплаты: цену и оплату вы согласуете с исполнителем напрямую":"Öffnen Sie den Katalog der Bauunternehmen und rufen Sie ein Team direkt an oder veröffentlichen Sie einen Auftrag im Feed — Auftragnehmer aus Ihrer Stadt senden Angebote mit Preis und Terminen. Die Anfrage wird ohne Vorauszahlung gesendet: Preis und Bezahlung vereinbaren Sie direkt mit dem Auftragnehmer",
