"Онлайн-оплата через платформу пока подключается. Сейчас заказы, бронь техники и материалы оплачиваются напрямую исполнителю или поставщику — Kaspi, переводом или по счёту для юрлиц":"Die Online-Zahlung über die Plattform wird derzeit eingerichtet. Aktuell werden Aufträge, Maschinenreservierungen und Materialien direkt beim Auftragnehmer oder Lieferanten bezahlt — per Kaspi, Überweisung oder auf Rechnung für Unternehmen",
