"Планировки часто нарисованы не в масштабе. Впишите реальную длину одной-двух сторон — например, размеры комнаты, подписанные на плане. Две стороны разного направления исправляют и растяжение плана по ширине и высоте":"Grundrisse sind oft nicht maßstäblich gezeichnet. Tragen Sie die echte Länge von ein bis zwei Seiten ein — zum Beispiel die auf dem Plan angegebenen Raummaße. Zwei Seiten unterschiedlicher Richtung korrigieren auch die Verzerrung des Plans in Breite und Höhe",
