"тонну":"Tonne",
"Точной позиции под этот запрос в базе не нашёл. Напишите конкретнее — вид работ или материал и объём, например «штукатурка стен {n} м²» или «бетон М{n} м³». А полную смету с работами и материалами соберёт [Смета по фото](auth:register)":"Eine genau passende Position zu dieser Anfrage habe ich in der Datenbank nicht gefunden. Schreiben Sie konkreter — Art der Arbeiten oder Material und Menge, zum Beispiel „Wandputz {n} m²“ oder „Beton M{n} m³“. Den vollständigen Kostenvoranschlag mit Arbeiten und Materialien erstellt [Kostenvoranschlag per Foto](auth:register)",
"штуку":"Stück",
